insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'hukuru-miskiy-old-friday-mosque', 'Hukuru Miskiy (Old Friday Mosque)', 'A UNESCO-listed 17th-century coral-stone mosque in Malé, famed for its intricate carvings and lacquer work.', 'published', 'Hukuru Miskiy (Old Friday Mosque) | Maldives Attractions | MTG', 'A UNESCO-listed 17th-century coral-stone mosque in Malé, famed for its intricate carvings and lacquer work.', '{"attraction_type":"religious","best_for":"History and architecture enthusiasts","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"Male Friday Mosque, also known as Hukuru Miskiy, is one of the oldest and most significant mosques in the Maldives. Built in 1658, it is renowned for its intricate coral stone architecture, traditional wood carvings and lacquer work, and is a UNESCO World Heritage tentative site. Visitors can explore the mosque''s ancient inscriptions, tombstones and architectural features to learn about the history and cultural heritage of the Maldives. The mosque is still active, so dress modestly and respect local customs while visiting."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
