insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'national-museum-male', 'The National Museum', 'The Maldives'' National Museum, housed in a former royal palace in Sultan Park, Malé.', 'published', 'The National Museum | Maldives Attractions | MTG', 'The Maldives'' National Museum, housed in a former royal palace in Sultan Park, Malé.', '{"attraction_type":"museum","best_for":"Families and history buffs","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"The National Museum of Maldives is located in Sultan Park, housed in a former royal palace. The museum showcases the rich history and culture of the Maldives, with exhibits ranging from ancient artifacts and royal regalia to traditional costumes and weapons. Visitors can learn about the Maldives'' history, from its Buddhist period to the Islamic era, through the museum''s extensive collection — an excellent stop for families and history buffs."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
