insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'mulee-aage-presidents-palace', 'Mulee''aage (The President''s Palace)', 'The official residence of the President of the Maldives, an early-20th-century colonial-style palace in Malé.', 'published', 'Mulee''aage (The President''s Palace) | Maldives Attractions | MTG', 'The official residence of the President of the Maldives, an early-20th-century colonial-style palace in Malé.', '{"attraction_type":"landmark","best_for":"A quick photo stop on a Malé walking tour","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"Mulee''aage, the official residence of the President of the Maldives, is a striking example of colonial architecture in Malé. Built in the early 20th century, the palace is known for its elaborate carvings, vibrant colors and well-manicured gardens. Visitors aren''t allowed inside, but the exterior offers a great photography spot and a popular stop on walking tours of Malé."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
