insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'sultan-park', 'Sultan Park and Rasrani Bageecha', 'A lush green park in the heart of Malé, once part of the royal palace grounds and home to the National Museum.', 'published', 'Sultan Park and Rasrani Bageecha | Maldives Attractions | MTG', 'A lush green park in the heart of Malé, once part of the royal palace grounds and home to the National Museum.', '{"attraction_type":"park","best_for":"Families wanting a relaxed break in central Malé","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"Sultan Park, also known as Rasrani Bageecha, is a lush green space in the heart of Malé, offering a peaceful retreat from the city''s hustle and bustle. The park was once part of the royal palace grounds and now features well-maintained gardens, playgrounds and water features. It''s an ideal spot for families to relax, with plenty of shaded areas, benches and play areas for children, and is also home to the National Museum — a convenient stop for those exploring Malé''s cultural sites."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
