insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'maldives-islamic-centre', 'Maldives Islamic Centre', 'A prominent Malé landmark topped by a large golden dome, home to the largest mosque in the Maldives.', 'published', 'Maldives Islamic Centre | Maldives Attractions | MTG', 'A prominent Malé landmark topped by a large golden dome, home to the largest mosque in the Maldives.', '{"attraction_type":"religious","best_for":"Learning about Islamic architecture and culture","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"The Maldives Islamic Centre is one of the most prominent landmarks in Malé. The centre is known for its large golden dome, which dominates the city''s skyline. The mosque inside is the largest in the Maldives and can accommodate over 5,000 worshippers. Visitors are welcome to explore the mosque outside of prayer times, providing an opportunity to learn about Islamic architecture and culture in the Maldives — the centre also hosts cultural events and exhibitions throughout the year."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
