insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'artificial-beach-male', 'Artificial Beach', 'A popular man-made beach on the eastern side of Malé, used for swimming, water sports and community events.', 'published', 'Artificial Beach | Maldives Attractions | MTG', 'A popular man-made beach on the eastern side of Malé, used for swimming, water sports and community events.', '{"attraction_type":"beach","best_for":"Swimming, sunset views, and local community events","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"Artificial Beach is a man-made beach located on the eastern side of Malé. It''s a popular spot for locals and tourists alike, offering a place to swim, relax and enjoy the sunset, and is a hub for various water sports and beach activities. The beach often hosts community events, including music festivals, parades and carnivals — a great place to experience local culture and enjoy some leisure time by the sea."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
