insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'victory-monument-male', 'Victory Monument', 'A Malé monument near Republic Square commemorating the government''s victory over a 1988 coup attempt.', 'published', 'Victory Monument | Maldives Attractions | MTG', 'A Malé monument near Republic Square commemorating the government''s victory over a 1988 coup attempt.', '{"attraction_type":"monument","best_for":"A quick stop on a Malé walking tour","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"The Victory Monument in Malé commemorates the victory of the Maldives government over a coup attempt in 1988. The monument is located near Republic Square and serves as a reminder of the country''s modern political history. It''s worth a quick visit for those interested in that history, and is located in a central area that''s easy to include in a walking tour of Malé."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
