insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'tsunami-monument-male', 'Tsunami Monument', 'A memorial on the southeastern side of Malé commemorating the lives lost in the 2004 Indian Ocean tsunami.', 'published', 'Tsunami Monument | Maldives Attractions | MTG', 'A memorial on the southeastern side of Malé commemorating the lives lost in the 2004 Indian Ocean tsunami.', '{"attraction_type":"monument","best_for":"A quiet, reflective stop with ocean views","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"The Tsunami Monument, located on the southeastern part of Malé, commemorates the lives lost in the 2004 Indian Ocean tsunami. The monument features a design with spheres representing the victims and steel rods symbolizing the impact of the waves. Visitors can reflect on the tragedy and resilience of the Maldivian people, with the surrounding area offering a peaceful environment with ocean views."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
