insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'male-fish-market', 'Malé Fish Market', 'A bustling working fish market in Malé where locals buy and sell the day''s catch, famous for feeding the resident stingrays.', 'published', 'Malé Fish Market | Maldives Attractions | MTG', 'A bustling working fish market in Malé where locals buy and sell the day''s catch, famous for feeding the resident stingrays.', '{"attraction_type":"market","best_for":"Experiencing everyday local life and culture","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"The Fish Market in Malé is a vibrant, bustling place where locals buy and sell fresh seafood — an excellent spot to witness the daily life of Malé''s residents and experience local food culture. Visitors can observe fishermen bringing in their catch of the day and even buy fresh fish to be cooked at nearby restaurants. The fishermen''s jetty in front of the market is where fish waste is discarded, a daily practice that draws stingrays which visitors can watch or feed."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
