insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'republic-square-male', 'Republic Square (Jumhooree Maidhaan)', 'Malé''s central public square, surrounded by government buildings and the site of national celebrations.', 'published', 'Republic Square (Jumhooree Maidhaan) | Maldives Attractions | MTG', 'Malé''s central public square, surrounded by government buildings and the site of national celebrations.', '{"attraction_type":"landmark","best_for":"Observing local culture and public events","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"Republic Square, also known as Jumhooree Maidhaan, is a central square in Malé that serves as a popular gathering place for locals. The square is surrounded by important government buildings, including the Presidential Palace and the headquarters of the Maldivian National Defence Force. It''s often the site of national celebrations, parades and other public events — a great place to observe local culture and the city''s atmosphere."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
