insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'sinamale-bridge', 'Sinamalé Bridge', 'The China-Maldives Friendship Bridge connecting Malé to Hulhulé Island and Velana International Airport.', 'published', 'Sinamalé Bridge | Maldives Attractions | MTG', 'The China-Maldives Friendship Bridge connecting Malé to Hulhulé Island and Velana International Airport.', '{"attraction_type":"infrastructure","best_for":"Sunset views and photography","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"The Sinamalé Bridge, also known as the China-Maldives Friendship Bridge, connects Malé with Hulhulé Island, where Velana International Airport is located. The bridge is a significant engineering achievement that has improved transportation between the islands. Visitors can walk or drive across it to enjoy panoramic views of the Indian Ocean and surrounding islands — it''s particularly beautiful at sunset, making it a popular photography spot."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
