insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, attributes, published_at) values ('location', 'rasfannu-beach', 'Rasfannu Beach', 'A small, popular urban beach on the western side of Malé, well known as a spot to watch the sunset.', 'published', 'Rasfannu Beach | Maldives Attractions | MTG', 'A small, popular urban beach on the western side of Malé, well known as a spot to watch the sunset.', '{"attraction_type":"beach","best_for":"Sunset views and a relaxed local beach atmosphere","source_article_slug":"beautiful-places-to-visit-in-maldives","body":"Rasfannu Beach is a small but popular urban beach located on the western side of Malé. The beach offers a convenient spot for swimming, sunbathing and relaxing, with facilities such as showers, changing rooms and food stalls nearby. It''s a great place to catch the sunset in Malé, well-maintained and with a laid-back atmosphere that makes it a favorite for both locals and tourists."}'::jsonb, now()) on conflict (node_type, slug) do nothing;
